\caption{\texttt{NSO}\xspace: \textbf{N}etwork \textbf{S}tability via Online Linear \textbf{O}ptimization}
\label{alg:stability}
\begin{algorithmic}[1]
\REQUIRE{Number of rounds $T$, set of servers ${\mathcal N}$ and links ${\mathcal L}$, maximum capacity $M$, feasible arrival rates $\Lambda$ (adversarial arrival rates given during execution -- only assumed in this section). An online linear optimization algorithm $\texttt{AdaPFOL}\xspace$ (\Cref{alg:OLO unbounded}).}
\STATE For each link $(n,m)\in {\mathcal L}$, initialize an instance of $\texttt{AdaPFOL}\xspace$ with action set $\triangle({\mathcal N})$ as $\texttt{AdaPFOL}\xspace_{n,m}$.
\FOR{$t=1,2,\ldots,T$}
\STATE For each link $(n,m)\in {\mathcal L}$, pass the maximum loss magnitude for this round $M\lVert \bm Q_m(t)-\bm Q_n(t)\rVert_\infty$ to $\texttt{AdaPFOL}\xspace_{n,m}$. Pick link allocation $\bm a_{n,m}(t)\in \triangle({\mathcal N})$ as the output of $\texttt{AdaPFOL}\xspace_{n,m}$.
\STATE Observe arrival rates $\bm \lambda(t)\in \Lambda$. \COMMENT{In the utility maximization algorithm \texttt{UMO}\textsuperscript{\texttt{2}}\xspace (\Cref{alg:utility}), this step will be replaced by another algorithmic component.}
\STATE Observe capacities $\{C_{n,m}(t)\}_{(n,m)\in {\mathcal L}}$ and actual data transmissions $\{\mu_{n,m}^{(k)}(t)\}_{(n,m)\in {\mathcal L},k\in {\mathcal N}}$.
\STATE Calculate queue lengths $\bm Q(t+1)$ from $\bm Q(t)$ according to \Cref{eq:multi-hop stability dynamics}.
\STATE For each link $(n,m)\in {\mathcal L}$, pass the loss vector $C_{n,m}(t)(\bm Q_m(t)-\bm Q_n(t))$ to $\texttt{AdaPFOL}\xspace_{n,m}$.
\ENDFOR
\end{algorithmic}

