&\quad -\frac 12 N^2 ((NM)^2+2(NM)^2+2R^2) T \nonumber\\
&\le \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{n\in {\mathcal N}} \sum_{k\in {\mathcal N}} Q_{n}^{(k)}(t) \left (\sum_{(o,n)\in {\mathcal L}} \mu_{o,n}^{(k)}(t) + \lambda_n^{(k)}(t) - \sum_{(n,m)\in {\mathcal L}} \mu_{n,m}^{(k)}(t) \right )\right ],\label{eq:multi-hop stability Lyapunov informal}
\end{align}

