&=\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{(n,m)\in {\mathcal L}} \langle \bm Q_m(t)-\bm Q_n(t),\bm \mu_{n,m}(t)\rangle\right ]\nonumber\\
&=\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{(n,m)\in {\mathcal L}} \langle C_{n,m}(t) (\bm Q_m(t)-\bm Q_n(t)),\bm a_{n,m}(t)\rangle\right ], \label{eq:multi-hop stability OLO objective informal}
\end{align}

\begin{equation*}
\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \langle C_{n,m}(t) (\bm Q_m(t)-\bm Q_n(t)),\bm a_{n,m}(t)\rangle\right ].
\end{equation*}

\begin{align}
&\quad \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]\lesssim \text{Online Learning Performance} \lesssim \operatorname{\mathcal O}_T(T) + o_T(T^{1/4}) \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]^{3/4} \nonumber \\
&\Longrightarrow \frac 1T \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ] = \operatorname{\mathcal O}_T(1),\textit{ i.e.},\text{ the system is stabilized}.\label{eq:self-bounding informal}
\end{align}

\label{def:multi-hop stability network stability}
There exists a reference action sequence $\{\mathring{\bm a}(t)\}_{t\in [T]}$ (where $\mathring{\bm a}(t)=\{\mathring{\bm a}_{n,m}(t)\in \triangle({\mathcal N})\}_{(n,m)\in {\mathcal L}}$, in analogue to the scheduler's action sequence), such that
there are some constants $C_W\ge 0$, $\epsilon_W\ge 0$ and a partition $W_1,W_2,\ldots,W_J$ of $[T]$,\footnote{A partition $W_1,W_2,\ldots,W_N$ of $[T]$ is a collection of a few non-intersecting intervals whose union is $[T]$} which ensure that $\sum_{j=1}^J (\lvert W_j\rvert-1)^2\le C_W T$ and
\begin{align}
&\frac{1}{\lvert W_j\rvert} \sum_{t\in W_j} \sum_{(n,m)\in {\mathcal L}} C_{n,m}(t) \mathring a_{n,m}^{(k)}(t) \ge \epsilon_W + \frac{1}{\lvert W_j\rvert} \sum_{t\in W_j} \left (\lambda_n^{(k)}(t) + \sum_{(o,n)\in {\mathcal L}} C_{o,n}(t) \mathring a_{o,n}^{(k)}(t)\right ), \nonumber\\
&\quad \forall j\in [J],n\in {\mathcal N},k\in {\mathcal N},\label{eq:multi-hop stability network stability}
\end{align}
where $\lambda_n^{(k)}(t)$ is the obliviously decided arrival rates that we assume in this section.

\begin{align}
&\frac{1}{\lvert W_j\rvert} \sum_{t\in W_j} \sum_{(n,m)\in {\mathcal L}} C_{n,m}(t) \mathring a_{n,m}^{(k)}(t) \ge \epsilon_W + \frac{1}{\lvert W_j\rvert} \sum_{t\in W_j} \left (\lambda_n^{(k)}(t) + \sum_{(o,n)\in {\mathcal L}} C_{o,n}(t) \mathring a_{o,n}^{(k)}(t)\right ), \nonumber\\
&\quad \forall j\in [J],n\in {\mathcal N},k\in {\mathcal N},\label{eq:multi-hop stability network stability}
\end{align}

\label{lem:multi-hop stability network stability}
If $\{\mathring{\bm a}(t)\}_{t\in [T]}$ satisfies \Cref{def:multi-hop stability network stability}, then for any scheduler-generated queue lengths $\{\bm Q(t)\}_{t\in [T]}$,
\begin{align*}
&\quad \epsilon_W \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{n\in {\mathcal N}} \sum_{k\in {\mathcal N}} Q_n^{(k)}(t)\right ] - (N^2 (2NM+R)^2 + \epsilon_W N^2 (2NM+R)) C_W T \\
&\le-\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{(n,m)\in {\mathcal L}} \sum_{k\in {\mathcal N}} C_{n,m}(t) \mathring{a}_{n,m}^{(k)}(t) (Q_m^{(k)}(t) - Q_n^{(k)}(t))\right ]-\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{n\in {\mathcal N}} \sum_{k\in {\mathcal N}} Q_n^{(k)}(t) \lambda_n^{(k)}(t)\right ].
\end{align*}

\begin{align*}
&\quad \epsilon_W \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{n\in {\mathcal N}} \sum_{k\in {\mathcal N}} Q_n^{(k)}(t)\right ] - (N^2 (2NM+R)^2 + \epsilon_W N^2 (2NM+R)) C_W T \\
&\le-\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{(n,m)\in {\mathcal L}} \sum_{k\in {\mathcal N}} C_{n,m}(t) \mathring{a}_{n,m}^{(k)}(t) (Q_m^{(k)}(t) - Q_n^{(k)}(t))\right ]-\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{n\in {\mathcal N}} \sum_{k\in {\mathcal N}} Q_n^{(k)}(t) \lambda_n^{(k)}(t)\right ].
\end{align*}

\begin{equation*}
\text{Lyapunov function }L_t=\frac 12 \sum_{n\in {\mathcal N}} \sum_{k\in {\mathcal N}} \left (Q_{n}^{(k)}\right )^2,\quad \text{Lyapunov drift } \Delta(\bm Q(t)) = \operatornamewithlimits{\mathbb{E}}[L_{t+1} - L_t \mid \bm Q(t)].
\end{equation*}

\label{lem:multi-hop stability Lyapunov}
Under the queue dynamics of \Cref{eq:multi-hop stability dynamics},
\begin{align}
0\le \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \Delta(\bm Q(t))\right ]&\le \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{(n,m)\in {\mathcal L}} \sum_{k\in {\mathcal N}} \mu_{n,m}^{(k)}(t)\left (Q_m^{(k)}(t)-Q_n^{(k)}(t)\right ) + \sum_{n\in {\mathcal N}} \sum_{k\in {\mathcal N}} Q_n^{(k)}(t) \lambda_n^{(k)}(t)\right ] + \nonumber \\
&\quad \frac 12 N^2 ((NM)^2+2(NM)^2+2R^2) T. \label{eq:multi-hop stability Lyapunov}
\end{align}

\begin{align}
0\le \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \Delta(\bm Q(t))\right ]&\le \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{(n,m)\in {\mathcal L}} \sum_{k\in {\mathcal N}} \mu_{n,m}^{(k)}(t)\left (Q_m^{(k)}(t)-Q_n^{(k)}(t)\right ) + \sum_{n\in {\mathcal N}} \sum_{k\in {\mathcal N}} Q_n^{(k)}(t) \lambda_n^{(k)}(t)\right ] + \nonumber \\
&\quad \frac 12 N^2 ((NM)^2+2(NM)^2+2R^2) T. \label{eq:multi-hop stability Lyapunov}
\end{align}

\begin{equation}\label{eq:multi-hop OLO objective}
\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \langle \bm \mu_{n,m}(t),\bm Q_m(t)-\bm Q_n(t)\rangle\right ]=\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \langle C_{n,m}(t) (\bm Q_m(t)-\bm Q_n(t)), \bm a_{n,m}(t)\rangle\right ],\quad \forall (n,m)\in {\mathcal L}.
\end{equation}

\label{def:OLO}
Consider a $T$-round game. Every round $t\in [T]$, the player selects an action $\bm x_t$ from a convex set $\mathcal X\subseteq \mathbb R^d$. The environment simultaneously decides a loss vector $\bm g_t\in \mathbb R^d$ such that the loss of the player for round $t$ is $\langle \bm x_t,\bm g_t\rangle$. The player will observe the whole vector of $\bm g_t$ (\textit{i.e.}, full-information feedback is available, instead of the more restrictive bandit feedback model). Dynamic regret minimization in OLO considers minimizing
\begin{equation*}
\text{D-Regret}_T^{\text{OLO}}(\mathring{\bm x}_1,\mathring{\bm x}_2,\ldots,\mathring{\bm x}_T)=\sum_{t=1}^T \langle \bm g_t,\bm x_t-\bm x_t^\circ\rangle,\quad \forall \mathring{\bm x}_1,\mathring{\bm x}_2,\ldots,\mathring{\bm x}_T\in \mathcal X.
\end{equation*}

\begin{equation*}
\text{D-Regret}_T^{\text{OLO}}(\mathring{\bm x}_1,\mathring{\bm x}_2,\ldots,\mathring{\bm x}_T)=\sum_{t=1}^T \langle \bm g_t,\bm x_t-\bm x_t^\circ\rangle,\quad \forall \mathring{\bm x}_1,\mathring{\bm x}_2,\ldots,\mathring{\bm x}_T\in \mathcal X.
\end{equation*}

\caption{\texttt{AdaPFOL}\xspace: \textbf{Ada}ptive \textbf{P}amameter-\textbf{F}ree \textbf{O}nline \textbf{L}earning}
\label{alg:OLO unbounded}
\begin{algorithmic}[1]
\REQUIRE{Action set $\mathcal X$. For each round $t$, the maximum loss magnitude $G_t$ will be reveled at the beginning, and a loss vector $\bm g_t$ satisfying $\lVert \bm g_t\rVert_\infty \le G_t$ will be given in the end.}
\STATE Set $G\gets 1$. Initialize an instance $\mathcal A$ of the algorithm in \Cref{lem:OLO guarantee} with action set $\mathcal X$.
\FOR{$t=1,2,\ldots$}
\STATE Observe the maximum loss magnitude $G_t>0$ for this round.
\IF{$G_t>G$}
\STATE Set $G=2G_t$. Reset $\mathcal A$ as a new instance of the algorithm in \Cref{lem:OLO guarantee} with action set $\mathcal X$.
\ENDIF
\STATE Output the ouptut of $\mathcal A$. Observe loss vector $\bm g_t$ (such that $\lVert \bm g_t\rVert_\infty\le G_t$). Feed $G^{-1}\bm g_t$ to $\mathcal A$.
\ENDFOR
\end{algorithmic}

\label{lem:OLO unbounded guarantee}
Consider the OLO problem in \Cref{def:OLO}. Let the action set $\mathcal X$ has diameter $D=\sup_{\bm x,\bm y\in \mathcal X}\lVert \bm x-\bm y\rVert_1$. Suppose that $\lVert \bm g_t\rVert_\infty\le G_t$, where $G_t$ is some $\mathcal F_{t-1}$-measurable random variable and $(\mathcal F_t)_{t=0}^T$ is the natural filtration, \textit{i.e.}, $\mathcal F_t$ is the $\sigma$-algebra generated by all random observations made during the first $t$ rounds.
Then, \texttt{AdaPFOL}\xspace (\Cref{alg:OLO unbounded}) ensures that for any comparator sequence $\mathring{\bm x}_1,\mathring{\bm x}_2,\ldots,\mathring{\bm x}_T\in \mathcal X$, if $\max_{t\in [T]} G_t\ge 1$, then
\begin{equation*}
\text{D-Regret}_T^{\text{OLO}}(\mathring{\bm x}_1,\mathring{\bm x}_2,\ldots,\mathring{\bm x}_T)=\operatorname{\mathcal O}\left (\sqrt{D \left (D+\sum_{t=1}^{T-1} \lVert \mathring{\bm x}_t-\mathring{\bm x}_{t+1}\rVert_1\right )}\sqrt{\sum_{t=1}^T \lVert \bm g_t\rVert_\infty^2}\log T \log \left (\max_{t=1}^T G_t\right )\right ).
\end{equation*}

\begin{equation*}
\text{D-Regret}_T^{\text{OLO}}(\mathring{\bm x}_1,\mathring{\bm x}_2,\ldots,\mathring{\bm x}_T)=\operatorname{\mathcal O}\left (\sqrt{D \left (D+\sum_{t=1}^{T-1} \lVert \mathring{\bm x}_t-\mathring{\bm x}_{t+1}\rVert_1\right )}\sqrt{\sum_{t=1}^T \lVert \bm g_t\rVert_\infty^2}\log T \log \left (\max_{t=1}^T G_t\right )\right ).
\end{equation*}

\label{remark:dynamic regret}
Note that in general, it is impossible to guarantee $\text{D-Regret}_T^{\text{OLO}}(\mathring{\bm x}_1,\mathring{\bm x}_2,\ldots,\mathring{\bm x}_T)=o_T(T)$ simultaneously for all $\{\mathring{\bm x}_t\in \mathcal X\}_{t\in [T]}$ \citep{zinkevich2003online}.
Therefore, many dynamic regret bounds, including ours,  depend on the notion of {path length} $P_T=\sum_{t=1}^{T-1} \lVert \mathring{\bm x}_t-\mathring{\bm x}_{t+1}\rVert$. Although the path length is linear in $T$ in the worst case, $\text{D-Regret}_T^{\text{OLO}}(\mathring{\bm x}_1,\mathring{\bm x}_2,\ldots,\mathring{\bm x}_T)=o_T(T)$ can still be ensured in cases where $P_T=o_T(T)$.

\label{thm:multi-hop stability decision making}
For each link $(n,m)\in {\mathcal L}$, as we did in \texttt{NSO}\xspace, we execute an instance of \texttt{AdaPFOL}\xspace (\Cref{alg:OLO unbounded}) where $\mathcal X=\triangle({\mathcal N})$, $\bm g_t=C_{n,m}(t) (\bm Q_m(t) - \bm Q_n(t))$, and $G_t=M\lVert \bm Q_m(t)-\bm Q_n(t)\rVert_\infty$. We make their outputs $\bm x_t$ as $\bm a_{n,m}(t)$ for every round $t$. Let $\mu_{n,m}^{(k)}(t)$ be the number of actually transmitted jobs from $Q_n^{(k)}(t)$ to $Q_m^{(k)}(t+1)$ induced by $a_{n,m}^{(k)}(t)$.

Consider an arbitrary reference action sequence $\{\mathring{\bm a} (t)\}_{t\in [T]}$ satisfying \Cref{def:multi-hop stability network stability}. Let $\mathring{\mu}_{n,m}^{(k)} (t)=C_{n,m}(t) \mathring{a}_{n,m}^{(k)} (t)\in [0,M]$ (as $C_{n,m}(t)\in [0,M]$ and $\mathring a_{n,m}^{(k)}(t)\in [0,1]$). Then
\begin{align*}
&\quad \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{(n,m)\in {\mathcal L}} \sum_{k\in {\mathcal N}} (\mu_{n,m}^{(k)}(t)-\mathring{\mu}_{n,m}^{(k)}(t))\left (Q_m^{(k)}(t)-Q_n^{(k)}(t)\right )\right ]\\
&=\operatorname{\mathcal O}\left (M\sqrt{1+P_T^a} \operatornamewithlimits{\mathbb{E}}\left [\sqrt{\sum_{t=1}^T \lVert \bm Q(t)\rVert_2^2} \log T \log \left (\max_{t=1}^T \max_{(n,m)\in {\mathcal L}} M \lVert \bm Q_m(t) - \bm Q_n(t)\rVert_\infty\right )\right ]\right )\text{,}
\end{align*}
where $P_T^a\triangleq \sum_{t=1}^{T-1} \sum_{(n,m)\in {\mathcal L}} \lVert \mathring{\bm a}_{n,m}(t) - \mathring{\bm a}_{n,m}(t+1)\rVert_1$ is the path length of $\{\mathring{\bm a}(t)\}_{t=1}^T$.

\begin{align*}
&\quad \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{(n,m)\in {\mathcal L}} \sum_{k\in {\mathcal N}} (\mu_{n,m}^{(k)}(t)-\mathring{\mu}_{n,m}^{(k)}(t))\left (Q_m^{(k)}(t)-Q_n^{(k)}(t)\right )\right ]\\
&=\operatorname{\mathcal O}\left (M\sqrt{1+P_T^a} \operatornamewithlimits{\mathbb{E}}\left [\sqrt{\sum_{t=1}^T \lVert \bm Q(t)\rVert_2^2} \log T \log \left (\max_{t=1}^T \max_{(n,m)\in {\mathcal L}} M \lVert \bm Q_m(t) - \bm Q_n(t)\rVert_\infty\right )\right ]\right )\text{,}
\end{align*}

\label{thm:multi-hop stability main theorem}
Suppose that $\{\mathring{\bm a}_{n,m}(t)\in \triangle({\mathcal N})\}_{(n,m)\in {\mathcal L},t\in [T]}$ satisfies \Cref{def:multi-hop stability network stability} and its path length satisfies \footnote{This assumption on path lengths comes from \citep[Assumption 2]{huang2023queue}. As discussed in \Cref{remark:dynamic regret}, such conditions are necessary.}
\begin{equation}\label{eq:network stability path length}
P_t^a\triangleq \sum_{s=1}^{t-1} \sum_{(n,m)\in {\mathcal L}} \lVert \mathring{\bm a}_{n,m}(s) - \mathring{\bm a}_{n,m}(s+1)\rVert_1\le C^a t^{1/2 - \delta_a},\quad \forall t=1,2,\ldots,T,
\end{equation}
where $C^a$ and $\delta_a$ are assumed to be known constants but the precise $P_t^a$ or $\{\mathring{\bm a}_{n,m}(t)\in \triangle({\mathcal N})\}_{(n,m)\in {\mathcal L},t\in [T]}$ both remain unknown.
Then, if we execute the \texttt{NSO}\xspace framework in \Cref{alg:stability} with \texttt{AdaPFOL}\xspace defined in \Cref{alg:OLO unbounded}, the following performance guarantee is enjoyed:
\begin{equation*}
\frac 1T\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]=\operatorname{\mathcal O}\left (\frac{(N^2(2NM+R)^2 + \epsilon_W N^2 (2NM+R))C_W + (N^4 M^2 + N^2 R^2)}{\epsilon_W}\right )+o_T(1).
\end{equation*}
That is, when $T\gg 0$, we have $\frac{1}{T} \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]=\operatorname{\mathcal O}_T(1)$, \textit{i.e.}, \Cref{eq:average queue} holds and the system is stable.

\begin{equation}\label{eq:network stability path length}
P_t^a\triangleq \sum_{s=1}^{t-1} \sum_{(n,m)\in {\mathcal L}} \lVert \mathring{\bm a}_{n,m}(s) - \mathring{\bm a}_{n,m}(s+1)\rVert_1\le C^a t^{1/2 - \delta_a},\quad \forall t=1,2,\ldots,T,
\end{equation}

\begin{equation*}
\frac 1T\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]=\operatorname{\mathcal O}\left (\frac{(N^2(2NM+R)^2 + \epsilon_W N^2 (2NM+R))C_W + (N^4 M^2 + N^2 R^2)}{\epsilon_W}\right )+o_T(1).
\end{equation*}

\begin{equation*}
\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]\le f(T) + g(T) \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]^{3/4} \log \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ],
\end{equation*}

\caption{\texttt{UMO}\textsuperscript{\texttt{2}}\xspace: \textbf{U}tility \textbf{M}aximization via Online Linear \textbf{O}ptimization and Bandit Convex \textbf{O}ptimization}
\label{alg:utility}
\begin{algorithmic}[1]
\REQUIRE{Number of rounds $T$, set of servers ${\mathcal N}$ and links ${\mathcal L}$, maximum capacity $M$, feasible arrival rates $\Lambda$. Parameter $V$. An online linear optimization algorithm $\texttt{AdaPFOL}\xspace$ (\Cref{alg:OLO unbounded}) and a bandit convex optimization algorithm $\texttt{AdaBGD}\xspace$ (\Cref{alg:ABGD}).}
\STATE For each link $(n,m)\in {\mathcal L}$, initialize an instance of $\texttt{AdaPFOL}\xspace$ with action set $\triangle({\mathcal N})$ as $\texttt{AdaPFOL}\xspace_{n,m}$.
\STATE {\color{blue} Initialize an instance of $\texttt{AdaBGD}\xspace$ with action set $\Lambda$.}
\FOR{$t=1,2,\ldots,T$}
\STATE For each link $(n,m)\in {\mathcal L}$, pass the maximum loss magnitude for this round $M\lVert \bm Q_m(t)-\bm Q_n(t)\rVert_\infty$ to $\texttt{AdaPFOL}\xspace_{n,m}$. Pick link allocation $\bm a_{n,m}(t)\in \triangle({\mathcal N})$ as the output of $\texttt{AdaPFOL}\xspace_{n,m}$.
\STATE {\color{blue}Call $\texttt{AdaBGD}\xspace$ with learning rates defined in \Cref{eq:true learning rate in BCO}. Pick arrival rates $\bm \lambda(t)\in \Lambda$ as its output.
\begin{align}
\eta_t&=\left (C^\lambda T^{1/2 - \delta_\lambda}\middle / \substack{\left (C^\lambda T^{1/2 - \delta_\lambda}\right )^{7/3} \left (4r^{-3} d^2 \right )^{28/9} \left (M+R\right )^{4/3}+\\
C^\lambda T^{1/2-\delta_\lambda} (r^{-3} d^2 VG^2 / L)^{4/3}+\\
\sum_{s=1}^t \left ((\lVert \bm q_s\rVert_\infty + VG)^2 (\lVert \bm q_s\rVert_2 + VL)^2\right )^{1/3}}\right )^{3/4}, \nonumber\\
\delta_t &= \left (\eta_t d^2 \frac{(\lVert \bm Q(t)\rVert_\infty + VG)^2}{(\lVert \bm Q(t)\rVert_2 + VL)}\right )^{1/3},\quad \alpha_t = \frac{\delta_t}{r}.\label{eq:true learning rate in BCO}
\end{align}}
\STATE Observe capacities $\{C_{n,m}(t)\}_{(n,m)\in {\mathcal L}}$ and actual data transmissions $\{\mu_{n,m}^{(k)}(t)\}_{(n,m)\in {\mathcal L},k\in {\mathcal N}}$.
\STATE Calculate queue lengths $\bm Q(t+1)$ from $\bm Q(t)$ according to \Cref{eq:multi-hop stability dynamics}.
\STATE For each link $(n,m)\in {\mathcal L}$, pass the loss vector $C_{n,m}(t)(\bm Q_m(t)-\bm Q_n(t))$ to $\texttt{AdaPFOL}\xspace_{n,m}$.
\STATE {\color{blue} Observe the collected utility $g_t(\bm \lambda(t))$. Pass the loss $\langle \bm Q(t),\bm \lambda (t)\rangle - V g_t(\bm \lambda(t))$ to $\texttt{AdaBGD}\xspace$.}
\ENDFOR
\end{algorithmic}

\begin{align}
\eta_t&=\left (C^\lambda T^{1/2 - \delta_\lambda}\middle / \substack{\left (C^\lambda T^{1/2 - \delta_\lambda}\right )^{7/3} \left (4r^{-3} d^2 \right )^{28/9} \left (M+R\right )^{4/3}+\\
C^\lambda T^{1/2-\delta_\lambda} (r^{-3} d^2 VG^2 / L)^{4/3}+\\
\sum_{s=1}^t \left ((\lVert \bm q_s\rVert_\infty + VG)^2 (\lVert \bm q_s\rVert_2 + VL)^2\right )^{1/3}}\right )^{3/4}, \nonumber\\
\delta_t &= \left (\eta_t d^2 \frac{(\lVert \bm Q(t)\rVert_\infty + VG)^2}{(\lVert \bm Q(t)\rVert_2 + VL)}\right )^{1/3},\quad \alpha_t = \frac{\delta_t}{r}.\label{eq:true learning rate in BCO}
\end{align}

\begin{align}
&\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{(n,m)\in {\mathcal L}} \langle C_{n,m}(t) (\bm Q_m(t) - \bm Q_n(t)), \bm a_{n,m}(t)\rangle\right ] + \nonumber\\
&\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{n\in {\mathcal N}} \langle \bm Q_n(t),\bm \lambda_n(t)\rangle\right ] - V \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \bigg (g_t(\bm \lambda(t) - g_t(\mathring{\bm \lambda}(t)))\bigg )\right ]\gtrsim 0,\label{eq:multi-hop utility Lyapunov informal}
