\label{def:multi-hop utility network stability}
There exists a {reference action sequence} $\{(\mathring{\bm a}(t),\mathring{\bm \lambda}(t))\}_{t\in [T]}$ (where $\mathring{\bm a}(t)=\{\mathring{\bm a}_{n,m}(t)\in \triangle({\mathcal N})\}_{(n,m)\in {\mathcal L}}$ and $\mathring{\bm \lambda}(t)=\{\mathring{\bm \lambda}_n(t)\in \Lambda_n\}_{n\in {\mathcal N}}$, in analogue to the scheduler's action sequence) such that there are constants $C_W\ge 0$, $\epsilon_W\ge 0$, and a partition $W_1,W_2,\ldots,W_J$ of $[T]$, such that $\sum_{j=1}^J (\lvert W_j\rvert-1)^2\le C_W T$ and
\begin{align*}
&\frac{1}{\lvert W_j\rvert} \sum_{t\in W_j} \sum_{(n,m)\in {\mathcal L}} C_{n,m}(t) \mathring a_{n,m}^{(k)}(t) \ge \epsilon_W + \frac{1}{\lvert W_j\rvert} \sum_{t\in W_j} \left (\mathring \lambda_n^{(k)}(t) + \sum_{(o,n)\in {\mathcal L}} C_{o,n}(t) \mathring a_{o,n}^{(k)}(t)\right ),\\
&\quad \forall j\in [J],n\in {\mathcal N},k\in {\mathcal N}.
\end{align*}

\begin{align*}
&\frac{1}{\lvert W_j\rvert} \sum_{t\in W_j} \sum_{(n,m)\in {\mathcal L}} C_{n,m}(t) \mathring a_{n,m}^{(k)}(t) \ge \epsilon_W + \frac{1}{\lvert W_j\rvert} \sum_{t\in W_j} \left (\mathring \lambda_n^{(k)}(t) + \sum_{(o,n)\in {\mathcal L}} C_{o,n}(t) \mathring a_{o,n}^{(k)}(t)\right ),\\
&\quad \forall j\in [J],n\in {\mathcal N},k\in {\mathcal N}.
\end{align*}

\label{lem:multi-hop utility network stability}
If $\{(\mathring{\bm a}(t),\mathring{\bm \lambda}(t))\}_{t\in [T]}$ satisfies \Cref{def:multi-hop utility network stability}, then for any scheduler-generated queue lengths $\{\bm Q(t)\}_{t\in [T]}$,
\begin{align}
&\quad \epsilon_W \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{n\in {\mathcal N}} \sum_{k\in {\mathcal N}} Q_n^{(k)}(t)\right ] - (N^2 (2NM+R)^2 + \epsilon_W N^2 (2NM+R)) C_W T \nonumber\\
&\le-\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{(n,m)\in {\mathcal L}}\sum_{k\in {\mathcal N}} \mathring \mu_{n,m}^{(k)}(t) (Q_m^{(k)}(t) - Q_n^{(k)}(t))\right ] - \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{n\in {\mathcal N}} \sum_{k\in {\mathcal N}} Q_n^{(k)}(t) \mathring \lambda_n^{(k)}(t)\right ].\label{eq:multi-hop utility network stability}
\end{align}

\begin{align}
&\quad \epsilon_W \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{n\in {\mathcal N}} \sum_{k\in {\mathcal N}} Q_n^{(k)}(t)\right ] - (N^2 (2NM+R)^2 + \epsilon_W N^2 (2NM+R)) C_W T \nonumber\\
&\le-\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{(n,m)\in {\mathcal L}}\sum_{k\in {\mathcal N}} \mathring \mu_{n,m}^{(k)}(t) (Q_m^{(k)}(t) - Q_n^{(k)}(t))\right ] - \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{n\in {\mathcal N}} \sum_{k\in {\mathcal N}} Q_n^{(k)}(t) \mathring \lambda_n^{(k)}(t)\right ].\label{eq:multi-hop utility network stability}
\end{align}

\begin{align}
&\quad -\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{(n,m)\in {\mathcal L}} \sum_{k\in {\mathcal N}} C_{n,m}(t) (Q_m^{(k)}(t)-Q_n^{(k)}(t))a_{n,m}^{(k)}(t)\right ] \nonumber\\
&\quad -\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{n\in {\mathcal N}} \sum_{k\in {\mathcal N}} Q_n^{(k)}(t) \lambda_n^{(k)}(t)\right ]+V \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T (g_t(\bm \lambda(t))-g_t(\mathring{\bm \lambda}(t)))\right ] \nonumber\\
&\le \frac 12 N^2 ((NM)^2+2(NM)^2+2R^2) T+V  \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T (g_t(\bm \lambda(t))-g_t(\mathring{\bm \lambda}(t)))\right ].\label{eq:multi-hop utility Lyapunov}
\end{align}

\begin{align}
&\scalemath{0.95}{-\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{(n,m)\in {\mathcal L}}\langle \mathring {\bm \mu}_{n,m}(t), \bm Q_m(t) - \bm Q_n(t)\rangle\right ]\lesssim -\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{(n,m)\in {\mathcal L}} \langle \bm \mu_{n,m}(t), \bm Q_m(t)-\bm Q_n(t)\rangle\right ],~ \text{and}} \nonumber\\
&\scalemath{0.95}{- \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{n\in {\mathcal N}} \langle \bm Q_n(t), \mathring {\bm \lambda}_n(t)\rangle\right ]\lesssim -\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{n\in {\mathcal N}} \langle \bm Q_n(t), \bm \lambda_n(t)\rangle\right ]+V \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \bigg (g_t(\bm \lambda(t))-g_t(\mathring{\bm \lambda}(t))\bigg )\right ].} \label{eq:multi-hop utility BCO objective}
\end{align}

\label{def:BCO}
Consider a $T$-round game. In round $t=1,2,\ldots,T$, the player picks an action $\bm x_t$ from a convex action set $\mathcal X\subseteq \mathbb R^d$, and the environment simultaneously picks an arbitrary convex loss $\ell_t\colon \mathcal X\to \mathbb R$. The player observes and suffers loss $\ell_t(\bm x_t)$. Dynamic regret minimization in BCO considers minimizing
\begin{equation*}
\text{D-Regret}_T^{\text{BCO}}(\bm u_1,\bm u_2,\ldots,\bm u_T)=\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T (\ell_t(\bm x_t)-\ell_t(\bm u_t))\right ],\quad \forall \bm u_1,\bm u_2,\ldots,\bm u_T\in \mathcal X.
\end{equation*}

\begin{equation*}
\text{D-Regret}_T^{\text{BCO}}(\bm u_1,\bm u_2,\ldots,\bm u_T)=\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T (\ell_t(\bm x_t)-\ell_t(\bm u_t))\right ],\quad \forall \bm u_1,\bm u_2,\ldots,\bm u_T\in \mathcal X.
\end{equation*}

\caption{\texttt{AdaBGD}\xspace: \textbf{A}daptive \textbf{B}andit \textbf{G}radient \textbf{D}escent}
\label{alg:ABGD}
\begin{algorithmic}[1]
\REQUIRE{Action set $\mathcal X$ bounded by $[r,R]$ (\textit{i.e.}, $r\mathbb B\subseteq \mathcal X\subseteq R\mathbb B$), hyper-parameters $\eta_1>\eta_2>\cdots>\eta_T$, $\delta_1,\delta_2,\ldots,\delta_T$, and $\alpha_t\triangleq \delta_t / r,\forall t\in [T]$.}
\STATE Initialize $\bm y_1=\bm 0$ (an internal variable of the algorithm).
\FOR{$t=1,2,\ldots,T$}
\STATE Calculate this round's action $\bm x_t\in \mathcal X$, observe loss $\ell_t(x_t)$, and update internal variable $\bm y_{t+1}$:
\begin{equation}\label{eq:ABGD}
\bm x_t=\bm y_t+\delta \bm s_t,\quad \bm y_{t+1}=\text{Proj}_{(1-\alpha_t)\mathcal X}\left [\bm y_t-\eta_t \frac{d}{\delta_t} \ell_t(\bm x_t) \bm s_t\right ],
\end{equation}
where $\bm s_t\in \mathbb R^d$ is a uniformly sampled unit vector used to estimate gradients \citep{flaxman2005online}.
\ENDFOR
\end{algorithmic}

\begin{equation}\label{eq:ABGD}
\bm x_t=\bm y_t+\delta \bm s_t,\quad \bm y_{t+1}=\text{Proj}_{(1-\alpha_t)\mathcal X}\left [\bm y_t-\eta_t \frac{d}{\delta_t} \ell_t(\bm x_t) \bm s_t\right ],
\end{equation}

\label{lem:ABGD guarantee}
Suppose that $r\mathbb B\subseteq \mathcal X\subseteq R\mathbb B$, the $t$-th loss $\ell_t$ is bounded by $C_t$ and is $L_t$-Lipschitz.
Suppose that $\eta_t$ and $\delta_t$ are both $\mathcal F_{t-1}$-measurable (where $(\mathcal F_t)_{t=0}^T$ is the natural filtration), $\eta_1>\eta_2>\cdots>\eta_T$, and $\alpha_t\triangleq \delta_t / r<1$ \textit{a.s.} for all $t\in [T]$. Then for any fixed $\bm u_1,\bm u_2,\ldots,\bm u_T\in \mathcal X$, the \texttt{AdaBGD}\xspace algorithm in \Cref{alg:ABGD} enjoys the following guarantee:
\begin{align*}
&\quad \text{D-Regret}_T^{\text{BCO}}(\bm u_1,\bm u_2,\ldots,\bm u_T)=\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T (\ell_t(\bm x_t)-\ell_t(\bm u_t))\right ]\\
&\le \operatornamewithlimits{\mathbb{E}}\left [\frac{7R^2}{4\eta_T}+\frac{P_T R}{\eta_T}+\sum_{t=1}^T \left (\frac{\eta_t}{2} \frac{d^2}{\delta_t^2} C_t^2 + 3L_t \delta_t + L_t \alpha_t R\right )\right ],
\end{align*}
where $P_T=\sum_{t=1}^{T-1}\lVert \bm u_t-\bm u_{t+1}\rVert$ is the path length of the comparator sequence $\{\bm u_t\}_{t\in [T]}$.

\begin{align*}
&\quad \text{D-Regret}_T^{\text{BCO}}(\bm u_1,\bm u_2,\ldots,\bm u_T)=\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T (\ell_t(\bm x_t)-\ell_t(\bm u_t))\right ]\\
&\le \operatornamewithlimits{\mathbb{E}}\left [\frac{7R^2}{4\eta_T}+\frac{P_T R}{\eta_T}+\sum_{t=1}^T \left (\frac{\eta_t}{2} \frac{d^2}{\delta_t^2} C_t^2 + 3L_t \delta_t + L_t \alpha_t R\right )\right ],
\end{align*}

\label{thm:multi-hop utility decision making}
For the reference arrival rates $\{\mathring{\bm \lambda}(t)\}_{t\in [T]}$ defined in \Cref{def:multi-hop utility network stability}, suppose that its path length ensures
\begin{equation*}
P_t^\lambda\triangleq \sum_{t=1}^{T-1} \lVert \mathring{\bm \lambda}({t+1}) - \mathring{\bm \lambda}(t)) \rVert_1\le C^\lambda t^{1/2 - \delta_\lambda},\quad \forall t=1,2,\ldots,T,
\end{equation*}
where, similar to \Cref{thm:multi-hop stability main theorem}, $C^\lambda$ and $\delta_\lambda$ are assumed to be known constants but the precise $P_t^\lambda$ or $\{\mathring{\bm \lambda}(t)\}_{t\in [T]}$ both remain unknown.
