If we execute \texttt{AdaBGD}\xspace (\Cref{alg:ABGD}) over $\Lambda$ with loss functions $\ell_t(\bm \lambda)=\langle \bm Q(t),\bm \lambda\rangle-V g_t(\bm \lambda)$ and parameters $\eta_t,\delta_t,\alpha_t$ defined in \Cref{eq:true learning rate in BCO} (restated below as \Cref{eq:true learning rate in BCO restatement} to ease reading):
\begin{align}
\eta_t&=\left (C^\lambda T^{1/2 - \delta_\lambda}\middle / \substack{\left (C^\lambda T^{1/2 - \delta_\lambda}\right )^{7/3} \left (4r^{-3} d^2 \right )^{28/9} \left (M+R\right )^{4/3}+\\
C^\lambda T^{1/2-\delta_\lambda} (r^{-3} d^2 VG^2 / L)^{4/3}+\\
\sum_{s=1}^t \left ((\lVert \bm q_s\rVert_\infty + VG)^2 (\lVert \bm q_s\rVert_2 + VL)^2\right )^{1/3}}\right )^{3/4}, \nonumber\\
\delta_t &= \left (\eta_t d^2 \frac{(\lVert \bm Q(t)\rVert_\infty + VG)^2}{(\lVert \bm Q(t)\rVert_2 + VL)}\right )^{1/3},\quad \alpha_t = \frac{\delta_t}{r},\label{eq:true learning rate in BCO restatement}
\end{align}
then the outputs $\bm \lambda(1),\bm \lambda(2),\ldots,\bm \lambda(T) \in \Lambda$ of \texttt{AdaBGD}\xspace ensure
\begin{align*}
&\scalemath{0.95}{\quad \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \left ((\langle \bm Q(t),\bm \lambda(t)\rangle - Vg_t(\bm \lambda(t))) - (\langle \bm Q(t),\mathring{\bm \lambda}(t)\rangle - Vg_t(\mathring{\bm \lambda}(t)))\right )\right ]}\\
&\scalemath{0.95}{=\operatorname{\mathcal O}\left (\frac{R(2NM+R)}{r^7} d^{14/3} (C^\lambda T^{1/2-\delta_\lambda})^2\right )+\operatorname{\mathcal O}\left (\operatornamewithlimits{\mathbb{E}}\left [\left (\frac{R}{r} d^{2/3}+R\right ) (C^\lambda T^{1/2 - \delta_\lambda})^{1/4} \left (\sum_{t=1}^T \left (\lVert \bm Q(t)\rVert_2 + V(L+G)\right )^{4/3}\right )^{3/4}\right ]\right ).}
\end{align*}

\begin{equation*}
P_t^\lambda\triangleq \sum_{t=1}^{T-1} \lVert \mathring{\bm \lambda}({t+1}) - \mathring{\bm \lambda}(t)) \rVert_1\le C^\lambda t^{1/2 - \delta_\lambda},\quad \forall t=1,2,\ldots,T,
\end{equation*}

\begin{align}
\eta_t&=\left (C^\lambda T^{1/2 - \delta_\lambda}\middle / \substack{\left (C^\lambda T^{1/2 - \delta_\lambda}\right )^{7/3} \left (4r^{-3} d^2 \right )^{28/9} \left (M+R\right )^{4/3}+\\
C^\lambda T^{1/2-\delta_\lambda} (r^{-3} d^2 VG^2 / L)^{4/3}+\\
\sum_{s=1}^t \left ((\lVert \bm q_s\rVert_\infty + VG)^2 (\lVert \bm q_s\rVert_2 + VL)^2\right )^{1/3}}\right )^{3/4}, \nonumber\\
\delta_t &= \left (\eta_t d^2 \frac{(\lVert \bm Q(t)\rVert_\infty + VG)^2}{(\lVert \bm Q(t)\rVert_2 + VL)}\right )^{1/3},\quad \alpha_t = \frac{\delta_t}{r},\label{eq:true learning rate in BCO restatement}
\end{align}

\begin{align*}
&\scalemath{0.95}{\quad \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \left ((\langle \bm Q(t),\bm \lambda(t)\rangle - Vg_t(\bm \lambda(t))) - (\langle \bm Q(t),\mathring{\bm \lambda}(t)\rangle - Vg_t(\mathring{\bm \lambda}(t)))\right )\right ]}\\
&\scalemath{0.95}{=\operatorname{\mathcal O}\left (\frac{R(2NM+R)}{r^7} d^{14/3} (C^\lambda T^{1/2-\delta_\lambda})^2\right )+\operatorname{\mathcal O}\left (\operatornamewithlimits{\mathbb{E}}\left [\left (\frac{R}{r} d^{2/3}+R\right ) (C^\lambda T^{1/2 - \delta_\lambda})^{1/4} \left (\sum_{t=1}^T \left (\lVert \bm Q(t)\rVert_2 + V(L+G)\right )^{4/3}\right )^{3/4}\right ]\right ).}
\end{align*}

\begin{equation}\label{eq:BCO regret decomposition informal}
\text{D-Regret}_T^{\text{BCO}}(\mathring{\bm \lambda}(1),\mathring{\bm \lambda}(2),\ldots,\mathring{\bm \lambda}(T))\lesssim \frac{C^\lambda T^{1/2-\delta_\lambda}}{\eta_T} + \sum_{t=1}^T \left (\eta_t C_t^2 L_t^2\right )^{1/3}.
\end{equation}

\label{thm:multi-hop utility main theorem}
Suppose that the feasible set of arrival rates vector $\Lambda$ is bounded by $[r,R]$.
Assume all (unknown) utility functions $g_t$ to be concave, $L$-Lipschitz, and $[-G,G]$-bounded.
Consider a reference action sequence $\{(\mathring{\bm a}(t),\mathring{\bm \lambda}(t))\}_{t\in [T]}$ satisfying \Cref{def:multi-hop utility network stability}, such that their path lengths satisfy
\begin{align*}
P_t^a\triangleq \sum_{s=1}^{t-1} \lVert \mathring{\bm a}(s)-\mathring{\bm a}(s+1)\rVert_1\le C^a t^{1/2-\delta_a},~P_t^\lambda\triangleq \sum_{s=1}^{t-1} \lVert \mathring{\bm \lambda}(s)-\mathring{\bm \lambda}(s+1)\rVert_1\le C^\lambda t^{1/2 - \delta_\lambda},\quad \forall t\in [T].
\end{align*}
Here, $M,R,r,L,G,C^a,\delta_a,C^\lambda,\delta_\lambda$ are assumed to be known constants, whereas the specific $\{(\mathring{\bm a}(t),\mathring{\bm \lambda}(t))\}_{t\in [T]}$ remains unknown.
If we execute the \texttt{UMO}\textsuperscript{\texttt{2}}\xspace framework in \Cref{alg:utility} with the $\texttt{AdaPFOL}\xspace$ sub-rountine given in \Cref{alg:OLO unbounded} and the $\texttt{AdaBGD}\xspace$ sub-routine given in \Cref{alg:ABGD}, when $T$ is large enough such that the constant $V=o_T(\min\{T^{2\delta_a/3},T^{2\delta_\lambda/7}\})$, the following inequalities hold simultaneously:
\begin{align*}
&\scalemath{0.95}{\frac 1T \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]=\operatorname{\mathcal O}\left (\frac{(N^2 (2NM+R)^2 + \epsilon_W N^2 (2NM+R)) C_W + (N^4 M^2+N^2 R^2)}{\epsilon_W}\right ) + o_T(1),}\\
&\scalemath{0.95}{\frac 1T \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \left (g_{t}(\mathring{\bm \lambda}(t)) - g_{t}(\bm \lambda(t))\right )\right ]=\operatorname{\mathcal O}\left (\frac{(N^2 (2NM+R)^2 + \epsilon_W N^2 (2NM+R)) C_W + (N^4 M^2+N^2 R^2)}{V}\right ) + o_T(V^{-1}).}
\end{align*}
That is, when $T\gg 0$, our algorithm not only stabilizes the system so that $\frac 1T \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]=\operatorname{\mathcal O}_T(1)$, but also enjoys an average utility approaching that of the reference policy polynomially fast, \textit{i.e.}, $\frac 1T \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \left (g_{t}(\mathring{\bm \lambda}(t)) - g_{t}(\bm \lambda(t))\right )\right ]=\operatorname{\mathcal O}_T(V^{-1})$ -- the utility maximization objective \Cref{eq:average reward} is ensured.

\begin{align*}
P_t^a\triangleq \sum_{s=1}^{t-1} \lVert \mathring{\bm a}(s)-\mathring{\bm a}(s+1)\rVert_1\le C^a t^{1/2-\delta_a},~P_t^\lambda\triangleq \sum_{s=1}^{t-1} \lVert \mathring{\bm \lambda}(s)-\mathring{\bm \lambda}(s+1)\rVert_1\le C^\lambda t^{1/2 - \delta_\lambda},\quad \forall t\in [T].
\end{align*}

\begin{align*}
&\scalemath{0.95}{\frac 1T \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]=\operatorname{\mathcal O}\left (\frac{(N^2 (2NM+R)^2 + \epsilon_W N^2 (2NM+R)) C_W + (N^4 M^2+N^2 R^2)}{\epsilon_W}\right ) + o_T(1),}\\
&\scalemath{0.95}{\frac 1T \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \left (g_{t}(\mathring{\bm \lambda}(t)) - g_{t}(\bm \lambda(t))\right )\right ]=\operatorname{\mathcal O}\left (\frac{(N^2 (2NM+R)^2 + \epsilon_W N^2 (2NM+R)) C_W + (N^4 M^2+N^2 R^2)}{V}\right ) + o_T(V^{-1}).}
\end{align*}

The first step of the proof is plugging the algorithmic guarantees for \texttt{AdaPFOL}\xspace (\Cref{thm:multi-hop stability decision making}) and for \texttt{AdaBGD}\xspace (\Cref{thm:multi-hop utility decision making}) into the reference policy assumption (\Cref{eq:multi-hop utility network stability}) and then making use of the Lyapunov DPP guarantee (\Cref{eq:multi-hop utility Lyapunov}). We present the detailed derivation in \Cref{lem:multi-hop utility tedious calc}. The conclusion reads
\begin{align}
\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]&\le -\frac{V}{\epsilon_W} \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \bigg (g_t(\mathring{\bm \lambda}(t)) - g_t(\bm \lambda(t))\bigg )\right ] + f(T) + \nonumber\\
&\quad g(T) \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]^{3/4} \log \operatornamewithlimits{\mathbb{E}} \left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ] + h(T) \operatornamewithlimits{\mathbb{E}} \left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]^{7/8},\label{eq:multi-hop utility self-bounding informal}
\end{align}
where $f(T)=\operatorname{\mathcal O}_T(T)$, $g(T)=\operatorname{\mathcal O}_T(T^{1/4-\delta_a/2})$, and $h(T)=\operatorname{\mathcal O}_T(T^{1/8-\delta_\lambda/4})$.

\paragraph{Step 1 (Develop a Coarse Average Queue Length Bound).} By the boundedness of $g_t$, the first term on the RHS of \Cref{eq:multi-hop utility self-bounding informal} is controlled by $\frac{V}{\epsilon_W} T G=\operatorname{\mathcal O}_T(VT)$ (note that, as $V=\text{poly}(T)$, $V$ is not a constant that can be hidden in $\operatorname{\mathcal O}_T$ and this term is actually super-linear).
Similar to the one used when proving \Cref{thm:multi-hop stability main theorem}, we develop another self-bounding property that says $y\le f+y^{3/4}g\log y +y^{7/8}h$ infers $y=\operatorname{\mathcal O}(f)+\operatorname{\widetilde{\mathcal O}}(g^{4}) + \operatorname{\mathcal O}(h^8)$ (see \Cref{lem:3/4 and 7/8 self-bounding}). Therefore,
\begin{equation*}
\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]=\operatorname{\mathcal O}_T\left (VT + T\right ) + \operatorname{\widetilde{\mathcal O}}_T\left (T^{1-2\delta_a}\right ) + \operatorname{\mathcal O}_T\left (T^{1 - 2 \delta_\lambda}\right )=\operatorname{\mathcal O}_T(VT),
\end{equation*}
only giving a $\frac 1T\operatornamewithlimits{\mathbb{E}}[\sum_{t=1}^T \lVert \bm Q(t)\rVert_1]=\operatorname{\mathcal O}_T(V)=\omega_T(1)$ bound on the average queue length (violating the system stability condition \Cref{eq:average queue}). However, this inequality can be used to derive the polynomial convergence result on the utility, which in turn further refines the queue length bound.

\paragraph{Step 2 (Yield Polynomial Convergence on the Utility).}
Moving the difference in the average utility to the LHS in \Cref{eq:multi-hop utility self-bounding informal} and plugging in the just-derived bound on average queue length, we have
\begin{align*}
\frac{V}{\epsilon_W T} \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \left (g_t(\mathring{\bm \lambda}(t)) - g_t(\bm \lambda(t)))\right )\right ]&=\operatorname{\mathcal O}_T\left (-0+\frac{f(T)}{T}+\frac{g(T)}{T}(VT)^{3/4}+\frac{h(T)}{T}(VT)^{7/8}\right )\\
&=\operatorname{\mathcal O}_T\left (1+\left (\frac{T^{1-2\delta_a}V^3}{T}\right )^{1/4}+\left (\frac{T^{1-2\delta_\lambda}V^7}{T}\right )^{1/8}\right ).
\end{align*}

According to the assumption that $V=\operatorname{\mathcal O}_T(\min\{T^{2\delta_a/3},T^{2\delta_\lambda/7}\})$, the RHS is of order $\operatorname{\mathcal O}_T(1)$. Thus
\begin{equation*}
\frac 1T \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \left (g_t(\mathring{\bm \lambda}(t)) - g_t(\bm \lambda(t)))\right )\right ]=\operatorname{\mathcal O}_T(V^{-1}),
\end{equation*}
\textit{i.e.}, a polynomial convergence rate on the expected average utility is derived.

\paragraph{Step 3 (Refine the Average Queue Length Bound).}
Now we are ready to refine our average queue length bound. Instead of controlling the utility with boundedness $g_t\in [-G,G]$, we utilize the just-derived convergence result and yields (again using the self-bounding property in \Cref{lem:3/4 and 7/8 self-bounding})
\begin{equation*}
\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]=\operatorname{\mathcal O}_T\left (V \times V^{-1} T + T\right ) + \operatorname{\widetilde{\mathcal O}}_T\left (T^{1-2\delta_a}\right ) + \operatorname{\mathcal O}_T\left (T^{1-2\delta_\lambda}\right )=\operatorname{\mathcal O}_T(T),
\end{equation*}
that is, the average queue length $\frac 1T\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]=\operatorname{\mathcal O}_T(1)$, which means \Cref{eq:average queue} holds and the system is stable. Putting Step 2 and Step 3 together gives our conclusion.

Once again, we omitted all factors except for those $\text{poly}(T)$ ones throughout this proof sketch. Please refer to \Cref{sec:multi-hop utility appendix} for the complete version.

