The proof almost follows that of \citet[Lemma 2]{huang2023queue}. We adapt their proof here for completeness.
For each interval $W_j$ in \Cref{def:multi-hop stability network stability}, let $T_0$ be the first round in $W_j$. Then
\begin{align*}
&\quad \sum_{t\in W_j} \sum_{n\in {\mathcal N}} \sum_{k\in {\mathcal N}} Q_n^{(k)}(t)\left (\sum_{(n,m)\in {\mathcal L}} C_{n,m}(t) \mathring a_{n,m}^{(k)}(t) - \lambda_n^{(k)}(t) - \sum_{(o,n)\in {\mathcal L}} C_{o,n}(t) \mathring a_{o,n}^{(k)}(t)\right ) \\
&=\sum_{t\in W_j} \sum_{n\in {\mathcal N}} \sum_{k\in {\mathcal N}} Q_n^{(k)}(T_0)\left (\sum_{(n,m)\in {\mathcal L}} C_{n,m}(t) \mathring a_{n,m}^{(k)}(t) - \lambda_n^{(k)}(t) - \sum_{(o,n)\in {\mathcal L}} C_{o,n}(t) \mathring a_{o,n}^{(k)}(t)\right ) + \\
&\quad \sum_{t\in W_j} \sum_{n\in {\mathcal N}} \sum_{k\in {\mathcal N}} \left (Q_n^{(k)}(t)-Q_n^{(k)}(T_0)\right )\left (\sum_{(n,m)\in {\mathcal L}} C_{n,m}(t) \mathring a_{n,m}^{(k)}(t) - \lambda_n^{(k)}(t) - \sum_{(o,n)\in {\mathcal L}} C_{o,n}(t) \mathring a_{o,n}^{(k)}(t)\right ).
\end{align*}

For the first term, we have the following for every $n\in {\mathcal N}$ and $k\in {\mathcal N}$, according to \Cref{def:multi-hop stability network stability}:
\begin{align*}
