\end{align*}

Thus, the first summation enjoys the following lower bound:
\begin{align*}
&\quad \sum_{t\in W_j} \sum_{n\in {\mathcal N}} \sum_{k\in {\mathcal N}} Q_n^{(k)}(T_0)\left (\sum_{(n,m)\in {\mathcal L}} C_{n,m}(t) \mathring a_{n,m}^{(k)}(t) - \lambda_n^{(k)}(t) - \sum_{(o,n)\in {\mathcal L}} C_{o,n}(t) \mathring a_{o,n}^{(k)}(t)\right ) \\
&\ge \left (\sum_{n\in {\mathcal N}} \sum_{k\in {\mathcal N}} Q_n^{(k)}(T_0)\right ) \epsilon_W \lvert W_j\rvert=\epsilon_W \lvert W_j\rvert \times \lVert \bm Q(T_0)\rVert_1\ge \epsilon_W \sum_{t\in W_j} \lVert \bm Q(t)\rVert_1-\epsilon_W N^2 (2NM+R) (\lvert W_j\rvert-1)^2,
\end{align*}
where the last step uses the fact that $\lVert \bm Q(t)\rVert_1 - \lVert \bm Q(T_0)\rVert_1\le \lVert \bm Q(t)-\bm Q(T_0)\rVert_1$ and the queue length increment bound in \Cref{lem:queue length increment}.

For the second summation, again utilizing the bound on $\lVert \bm Q(t)-\bm Q(T_0)\rVert_1$, we have
