&\ge -\sum_{t\in W_j} \lVert \bm Q(t)-\bm Q(T_0)\rVert_1\times \max_{t\in W_j} \max_{n\in {\mathcal N}} \max_{k\in {\mathcal N}} \left \lvert \sum_{(n,m)\in {\mathcal L}} C_{n,m}(t) \mathring a_{n,m}^{(k)}(t) - \lambda_n^{(k)}(t) - \sum_{(o,n)\in {\mathcal L}} C_{o,n}(t) \mathring a_{o,n}^{(k)}(t) \right \rvert \\
&\ge -N^2 (2NM+R) (\lvert W_j\rvert-1)^2\times (2NM+R)=-N^2 (2NM+R)^2 (\lvert W_j\rvert-1)^2.
\end{align*}

Therefore, recall the assumption that $\sum_{j\in [J]}(\lvert W_j\rvert-1)^2\le C_W T$, summing over $j=1,2,\ldots,J$ gives
\begin{align*}
&\quad \epsilon_W \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \sum_{n\in {\mathcal N}} \sum_{k\in {\mathcal N}} Q_n^{(k)}(t)\right ] - (N^2 (2NM+R)^2 + \epsilon_W N^2 (2NM+R)) C_W T \\
