&\quad 2 \left [Q_n^{(k)}(t)-\sum_{(n,m)\in {\mathcal L}}\mu_{n,m}^{(k)}(t)\right ]_+\left (\sum_{(o,n)\in {\mathcal L}} \mu_{o,n}^{(k)}(t) + \lambda_{n}^{(k)}(t)\right )\\
