&\quad \frac 12 \sum_{n\in {\mathcal N}} \sum_{k\in {\mathcal N}} \operatornamewithlimits{\mathbb{E}}\left [\left (\sum_{(n,m)\in {\mathcal L}}\mu_{n,m}^{(k)}(t)\right )^2 + \left (\sum_{(o,n)\in {\mathcal L}} \mu_{o,n}^{(k)}(t) + \lambda_{n}^{(k)}(t)\right )^2\middle \vert \bm Q(t)\right ].
