&=\operatorname{\mathcal O}\left (\operatornamewithlimits{\mathbb{E}}\left [\frac{R^2 + C^r T^{1/2 - \delta_r} R}{\eta_T}+\sum_{t=1}^T \left (\eta_t d^2 (\lVert \bm Q(t)\rVert_\infty + VG)^2 (\lVert \bm Q(t)\rVert_2 + VL)^2\right )^{1/3} \frac{R}{r}\right ]\right ). \label{eq:BCO regret decomposition}
\end{align}

We first only keep the last term in \Cref{eq:true learning rate in BCO appendix}, \textit{i.e.}, let
\begin{equation}\label{eq:learning rate in BCO}
\eta_t = \left (C^r T^{1/2 - \delta_r}\middle / \sum_{s=1}^t \left ((\lVert \bm q_s\rVert_\infty + VG)^2 (\lVert \bm q_s\rVert_2 + VL)^2\right )^{1/3}\right )^{3/4},
\end{equation}
then we have $\eta_1>\eta_2>\cdots >\eta_T$. Let's first pretend the other condition of $\alpha_t<1$ from \Cref{lem:ABGD guarantee} also holds at this moment.
\Cref{lem:3/4 summation lemma} reveals that if $x_1,x_2,\ldots,x_T\ge 0$, then $\left .\sum_{t=1}^T x_t \middle / (\sum_{s\le t} x_s)^{1/4} \right . =\operatorname{\mathcal O}\left (\left (\sum_{t=1}^T x_t\right )^{3/4}\right )$. Plugging in $x_t=\left (\lVert \bm q_s\rVert_\infty + VG)^2 (\lVert \bm q_s\rVert_2 + VL)^2\right )^{1/3}$,
\begin{align*}
&\quad \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T (\ell_t(\bm \lambda_t)-\ell_t(\bm \lambda_t^\ast))\right ] \\
&=\operatorname{\mathcal O}\left (\operatornamewithlimits{\mathbb{E}}\left [(C^r T^{1/2 - \delta_r})^{1/4} R \left (\sum_{t=1}^T \left ((\lVert \bm Q(t)\rVert_\infty + VG)^2 (\lVert \bm Q(t)\rVert_2 + VL)^2\right )^{1/3}\right )^{3/4} \right ]\right . + \\
&\qquad \left .\operatornamewithlimits{\mathbb{E}}\left [\frac{R}{r} \left (C^r T^{1/2 - \delta_r}\right )^{1/4} d^{2/3} \left (\sum_{t=1}^T \left ((\lVert \bm Q(t)\rVert_\infty + VG)^2 (\lVert \bm Q(t)\rVert_2 + VL)^2\right )^{1/3}\right )^{3/4} \right ] \right )\\
&=\operatorname{\mathcal O}\left (\operatornamewithlimits{\mathbb{E}}\left [\left (\frac{R}{r} d^{2/3}+R\right ) (C^r T^{1/2 - \delta_r})^{1/4} \left (\sum_{t=1}^T \left (\lVert \bm Q(t)\rVert_2 + V(L+G)\right )^{4/3}\right )^{3/4}\right ]\right ),
\end{align*}
where the last step utilizes $\lVert \bm Q(t)\rVert_\infty \le \lVert \bm Q(t)\rVert_2$.

This almost recovers our conclusion, so it only remains to ensure $\alpha_t=\delta_t/r<1$, which is equivalent to $\eta_t d^2 C_t^2 / L_t < r^3$, \textit{i.e.},
\begin{equation*}
\eta_t^{-1} > r^{-3} d^2 \frac{(\lVert \bm Q(t)\rVert_\infty + VG)^2}{\lVert \bm Q(t)\rVert_2 + VL}.
\end{equation*}

Consider adding a term $X$ into the denominator of \Cref{eq:learning rate in BCO}.
As $\lVert \bm Q(t)\rVert_\infty \le \lVert \bm Q(t)\rVert_2$, $(\lVert \bm Q(t)\rVert_\infty + VG)^2 / (\lVert \bm Q(t)\rVert_2 + VL)\le 2 (\lVert \bm Q(t)\rVert_\infty^2 / \lVert \bm Q(t)\rVert_2) + 2 ((VG)^2 / (VL))\le 2 \lVert \bm Q(t)\rVert_\infty + 2 VG^2 / L$. So we only need to show
\begin{align*}
\frac{\left (X + \sum_{s=1}^t \left ((\lVert \bm q_s\rVert_\infty + VG)^2 (\lVert \bm q_s\rVert_2 + VL)^2\right )^{1/3}\right )^{3/4}}{(C^r T^{1/2 - \delta_r})^{3/4}} > 2 r^{-3} d^2 \left (\lVert \bm Q(t)\rVert_\infty + V \frac{G^2}{L}\right ).
\end{align*}

We decompose $X$ into $X_1$ and $X_2$ and use them to cancel the two terms on the RHS, respectively. That is, we want
\begin{align*}
X_1 + \sum_{s=1}^t \left (\lVert \bm q_s\rVert_\infty^2 \lVert \bm q_s\rVert_2^2\right )^{1/3} & > C^r T^{1/2 - \delta_r} \left (r^{-3} d^2 \lVert \bm Q(t)\rVert_\infty\right )^{4/3},\\
X_2 + t^{3/4} (V^4 G^2 L^2)^{1/4} & > C^r T^{1/2 - \delta_r} \left (r^{-3} d^2 V G^2 / L\right )^{4/3}.
\end{align*}

We first craft $X_1$.
In \Cref{lem:4/3 lower bound}, we show that if $x_1=0$, $x_2,\ldots,x_T \ge 0$, and $\lvert x_{t+1}-x_t\rvert\le 1$, then $\sum_{t=1}^T x_t^{4/3} \ge (x_T/4)^{7/3}$. Thus, using the fact that $\lVert \bm Q(t)\rVert_\infty\le \lVert \bm Q(t)\rVert_2$ and the queue length increment bound $\lvert \lVert \bm Q(t+1)\rVert_\infty - \lVert \bm Q(t)\rVert_\infty \rvert\le (2NM+R)$ (\Cref{lem:queue length increment}), we can let $x_t=\lVert \bm Q(t)\rVert_\infty / (2NM+R)$ and lower bound the LHS by
\begin{equation*}
X_1 + \sum_{s=1}^t \left (\lVert \bm q_s\rVert_\infty^2 \lVert \bm q_s\rVert_2^2\right )^{1/3}\ge X_1+\frac{\left (\lVert \bm Q(t)\rVert_\infty / 4 \right )^{7/3}}{(2NM+R)}\ge X_1^{3/7} \left (\frac{\left (\lVert \bm Q(t)\rVert_\infty / 4 \right )^{7/3}}{(2NM+R)}\right )^{4/7},
\end{equation*}
where the inequality results from AM-GM inequality $\frac{ax + by}{a+b} \ge \sqrt[a+b]{x^a y^b}$. Therefore, we only need to ensure $X_1^{3/7}\ge C^r T^{1/2-\delta_r} (4 r^{-3} d^2)^{4/3} (2NM+R)^{4/7}$. Setting $X_1$ as following then suffices.
\begin{equation*}
X_1=\left (C^r T^{1/2 - \delta_r}\right )^{7/3} \left (4r^{-3} d^2 \right )^{28/9} \left ((2NM+R)\right )^{4/3}.
\end{equation*}

For $X_2$, we only need to set $X_2 = C^r T^{1/2-\delta_r} (r^{-3} d^2 VG^2 / L)^{4/3}$.
Plugging back $X=X_1+X_2$, we get the learning rate scheduling defined in \Cref{eq:true learning rate in BCO appendix}.
Now we verify that the two terms on the RHS of \Cref{eq:BCO regret decomposition} does not increase too much due to $X$. For the first term,
\begin{align*}
&\quad \operatornamewithlimits{\mathbb{E}}\left [\frac{R^2 + C^r T^{1/2 - \delta_r} R}{\eta_T}\right ]\\
&=\left [\frac{R^2 + C^r T^{1/2 - \delta_r} R}{(C^r T^{1/2 - \delta_r})^{3/4}}\left (X + \sum_{t=1}^T \left ((\lVert \bm Q(t)\rVert_\infty + VG)^2 (\lVert \bm Q(t)\rVert_2 + VL)^2\right )^{1/3}\right )^{3/4}\right ]\\
&=\operatorname{\mathcal O}\left (\operatornamewithlimits{\mathbb{E}}\left [\left (C^r T^{1/2 - \delta_r} R\right ) \left (\frac{X}{C^r T^{1/2 - \delta_r}}\right )^{3/4}+(C^r T^{1/2 - \delta_r})^{1/4} R \left (\sum_{t=1}^T \left (\lVert \bm Q(t)\rVert_2 + V(L+G)\right )^{4/3} \right )^{3/4}\right ]\right )\\
&=\operatorname{\mathcal O} \left (\operatornamewithlimits{\mathbb{E}}\left [\frac{R(2NM+R)}{r^7} d^{14/3} (C^r T^{1/2-\delta_r})^2 + R (C^r T^{1/2 - \delta_r})^{1/4} \left (\sum_{s=1}^t \left (\lVert \bm q_s\rVert_2 + V(L+G)\right )^{4/3} \right )^{3/4}\right ]\right ).
\end{align*}

For the second term, as $\eta_t$ is strictly smaller than that in \Cref{eq:learning rate in BCO}, we can again apply \Cref{lem:3/4 summation lemma} (if $x_1,x_2,\ldots,x_T\ge 0$, then $\left .\sum_{t=1}^T x_t \middle / (\sum_{s\le t} x_s)^{1/4} \right . =\operatorname{\mathcal O}\left (\left (\sum_{t=1}^T x_t\right )^{3/4}\right )$) to conclude
\begin{align*}
&\quad \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \left (\eta_t d^2 (\lVert \bm Q(t)\rVert_\infty + VG)^2 (\lVert \bm Q(t)\rVert_2 + VL)^2\right )^{1/3} \frac{R}{r}\right ]\\
&=\operatornamewithlimits{\mathbb{E}}\left [\frac{R}{r} d^{2/3} (C^r T^{1/2 - \delta_r})^{1/4} \left (\sum_{t=1}^T \left (\lVert \bm Q(t)\rVert_2 + V(L+G)\right )^{4/3}\right )^{3/4}\right ].
\end{align*}

Summing up two parts gives our conclusion.

\begin{align}
&\quad \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T (\ell_t(\bm \lambda_t)-\ell_t(\bm \lambda_t^\ast))\right ]\le \operatornamewithlimits{\mathbb{E}}\left [\frac{7R^2 + 4 P_T R}{4\eta_T} + \sum_{t=1}^T \left (\eta_t \frac{d^2}{\delta_t^2} C_t^2 + 3L_t\delta_t + L_t \alpha_t R\right )\right ] \nonumber\\
&=\operatorname{\mathcal O}\left (\operatornamewithlimits{\mathbb{E}}\left [\frac{R^2 + C^r T^{1/2 - \delta_r} R}{\eta_T}+\sum_{t=1}^T \left (\eta_t d^2 (\lVert \bm Q(t)\rVert_\infty + VG)^2 (\lVert \bm Q(t)\rVert_2 + VL)^2\right )^{1/3} \frac{R}{r}\right ]\right ). \label{eq:BCO regret decomposition}
\end{align}

\begin{equation}\label{eq:learning rate in BCO}
\eta_t = \left (C^r T^{1/2 - \delta_r}\middle / \sum_{s=1}^t \left ((\lVert \bm q_s\rVert_\infty + VG)^2 (\lVert \bm q_s\rVert_2 + VL)^2\right )^{1/3}\right )^{3/4},
\end{equation}

\begin{align*}
&\quad \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T (\ell_t(\bm \lambda_t)-\ell_t(\bm \lambda_t^\ast))\right ] \\
&=\operatorname{\mathcal O}\left (\operatornamewithlimits{\mathbb{E}}\left [(C^r T^{1/2 - \delta_r})^{1/4} R \left (\sum_{t=1}^T \left ((\lVert \bm Q(t)\rVert_\infty + VG)^2 (\lVert \bm Q(t)\rVert_2 + VL)^2\right )^{1/3}\right )^{3/4} \right ]\right . + \\
&\qquad \left .\operatornamewithlimits{\mathbb{E}}\left [\frac{R}{r} \left (C^r T^{1/2 - \delta_r}\right )^{1/4} d^{2/3} \left (\sum_{t=1}^T \left ((\lVert \bm Q(t)\rVert_\infty + VG)^2 (\lVert \bm Q(t)\rVert_2 + VL)^2\right )^{1/3}\right )^{3/4} \right ] \right )\\
&=\operatorname{\mathcal O}\left (\operatornamewithlimits{\mathbb{E}}\left [\left (\frac{R}{r} d^{2/3}+R\right ) (C^r T^{1/2 - \delta_r})^{1/4} \left (\sum_{t=1}^T \left (\lVert \bm Q(t)\rVert_2 + V(L+G)\right )^{4/3}\right )^{3/4}\right ]\right ),
\end{align*}

\begin{equation*}
\eta_t^{-1} > r^{-3} d^2 \frac{(\lVert \bm Q(t)\rVert_\infty + VG)^2}{\lVert \bm Q(t)\rVert_2 + VL}.
\end{equation*}

\begin{align*}
\frac{\left (X + \sum_{s=1}^t \left ((\lVert \bm q_s\rVert_\infty + VG)^2 (\lVert \bm q_s\rVert_2 + VL)^2\right )^{1/3}\right )^{3/4}}{(C^r T^{1/2 - \delta_r})^{3/4}} > 2 r^{-3} d^2 \left (\lVert \bm Q(t)\rVert_\infty + V \frac{G^2}{L}\right ).
\end{align*}

\begin{align*}
X_1 + \sum_{s=1}^t \left (\lVert \bm q_s\rVert_\infty^2 \lVert \bm q_s\rVert_2^2\right )^{1/3} & > C^r T^{1/2 - \delta_r} \left (r^{-3} d^2 \lVert \bm Q(t)\rVert_\infty\right )^{4/3},\\
X_2 + t^{3/4} (V^4 G^2 L^2)^{1/4} & > C^r T^{1/2 - \delta_r} \left (r^{-3} d^2 V G^2 / L\right )^{4/3}.
\end{align*}

\begin{equation*}
X_1 + \sum_{s=1}^t \left (\lVert \bm q_s\rVert_\infty^2 \lVert \bm q_s\rVert_2^2\right )^{1/3}\ge X_1+\frac{\left (\lVert \bm Q(t)\rVert_\infty / 4 \right )^{7/3}}{(2NM+R)}\ge X_1^{3/7} \left (\frac{\left (\lVert \bm Q(t)\rVert_\infty / 4 \right )^{7/3}}{(2NM+R)}\right )^{4/7},
\end{equation*}

\begin{equation*}
X_1=\left (C^r T^{1/2 - \delta_r}\right )^{7/3} \left (4r^{-3} d^2 \right )^{28/9} \left ((2NM+R)\right )^{4/3}.
\end{equation*}

\begin{align*}
&\quad \operatornamewithlimits{\mathbb{E}}\left [\frac{R^2 + C^r T^{1/2 - \delta_r} R}{\eta_T}\right ]\\
&=\left [\frac{R^2 + C^r T^{1/2 - \delta_r} R}{(C^r T^{1/2 - \delta_r})^{3/4}}\left (X + \sum_{t=1}^T \left ((\lVert \bm Q(t)\rVert_\infty + VG)^2 (\lVert \bm Q(t)\rVert_2 + VL)^2\right )^{1/3}\right )^{3/4}\right ]\\
&=\operatorname{\mathcal O}\left (\operatornamewithlimits{\mathbb{E}}\left [\left (C^r T^{1/2 - \delta_r} R\right ) \left (\frac{X}{C^r T^{1/2 - \delta_r}}\right )^{3/4}+(C^r T^{1/2 - \delta_r})^{1/4} R \left (\sum_{t=1}^T \left (\lVert \bm Q(t)\rVert_2 + V(L+G)\right )^{4/3} \right )^{3/4}\right ]\right )\\
&=\operatorname{\mathcal O} \left (\operatornamewithlimits{\mathbb{E}}\left [\frac{R(2NM+R)}{r^7} d^{14/3} (C^r T^{1/2-\delta_r})^2 + R (C^r T^{1/2 - \delta_r})^{1/4} \left (\sum_{s=1}^t \left (\lVert \bm q_s\rVert_2 + V(L+G)\right )^{4/3} \right )^{3/4}\right ]\right ).
\end{align*}

\begin{align*}
&\quad \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \left (\eta_t d^2 (\lVert \bm Q(t)\rVert_\infty + VG)^2 (\lVert \bm Q(t)\rVert_2 + VL)^2\right )^{1/3} \frac{R}{r}\right ]\\
&=\operatornamewithlimits{\mathbb{E}}\left [\frac{R}{r} d^{2/3} (C^r T^{1/2 - \delta_r})^{1/4} \left (\sum_{t=1}^T \left (\lVert \bm Q(t)\rVert_2 + V(L+G)\right )^{4/3}\right )^{3/4}\right ].
\end{align*}

Suppose that the feasible set of arrival rates vector $\Lambda$ is bounded by $[r,R]$.
Assume all (unknown) utility functions $g_t$ to be concave, $L$-Lipschitz, and $[-G,G]$-bounded.
Consider a reference action sequence $\{(\mathring{\bm a}(t),\mathring{\bm \lambda}(t))\}_{t\in [T]}$ satisfying \Cref{def:multi-hop utility network stability}, such that their path lengths satisfy
\begin{align*}
P_t^a\triangleq \sum_{s=1}^{t-1} \lVert \mathring{\bm a}(s)-\mathring{\bm a}(s+1)\rVert_1\le C^a t^{1/2-\delta_a},~P_t^\lambda\triangleq \sum_{s=1}^{t-1} \lVert \mathring{\bm \lambda}(s)-\mathring{\bm \lambda}(s+1)\rVert_1\le C^\lambda t^{1/2 - \delta_\lambda},\quad \forall t\in [T].
\end{align*}
Here, $M,R,r,L,G,C^a,\delta_a,C^\lambda,\delta_\lambda$ are assumed to be known constants, whereas the specific $\{(\mathring{\bm a}(t),\mathring{\bm \lambda}(t))\}_{t\in [T]}$ remains unknown.
If we execute the \texttt{UMO}\textsuperscript{\texttt{2}}\xspace framework in \Cref{alg:utility} with the $\texttt{AdaPFOL}\xspace$ sub-rountine given in \Cref{alg:OLO unbounded} and the $\texttt{AdaBGD}\xspace$ sub-routine given in \Cref{alg:ABGD}, when $T$ is large enough such that $V=o_T(\min\{T^{2\delta_a/3},T^{2\delta_\lambda/7}\})$, the following inequalities hold simultaneously:
\begin{align*}
&\scalemath{0.95}{\frac 1T \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]=\operatorname{\mathcal O}\left (\frac{(N^2 (2NM+R)^2 + \epsilon_W N^2 (2NM+R)) C_W + (N^4 M^2+N^2 R^2)}{\epsilon_W}\right ) + o_T(1),}\\
&\scalemath{0.95}{\frac 1T \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \left (g_{t}(\mathring{\bm \lambda}(t)) - g_{t}(\bm \lambda(t))\right )\right ]=\operatorname{\mathcal O}\left (\frac{(N^2 (2NM+R)^2 + \epsilon_W N^2 (2NM+R)) C_W + (N^4 M^2+N^2 R^2)}{V}\right ) + o_T(V^{-1}).}
\end{align*}
That is, when $T\gg 0$, our algorithm not only stabilizes the system so that $\frac 1T \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]=\operatorname{\mathcal O}_T(1)$, but also enjoys an average utility approaching that of the reference policy polynomially fast, \textit{i.e.}, $\frac 1T \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \left (g_{t}(\mathring{\bm \lambda}(t)) - g_{t}(\bm \lambda(t))\right )\right ]=\operatorname{\mathcal O}_T(V^{-1})$ -- the utility maximization objective \Cref{eq:average reward} is ensured.

\begin{align*}
P_t^a\triangleq \sum_{s=1}^{t-1} \lVert \mathring{\bm a}(s)-\mathring{\bm a}(s+1)\rVert_1\le C^a t^{1/2-\delta_a},~P_t^\lambda\triangleq \sum_{s=1}^{t-1} \lVert \mathring{\bm \lambda}(s)-\mathring{\bm \lambda}(s+1)\rVert_1\le C^\lambda t^{1/2 - \delta_\lambda},\quad \forall t\in [T].
\end{align*}

\begin{align*}
&\scalemath{0.95}{\frac 1T \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]=\operatorname{\mathcal O}\left (\frac{(N^2 (2NM+R)^2 + \epsilon_W N^2 (2NM+R)) C_W + (N^4 M^2+N^2 R^2)}{\epsilon_W}\right ) + o_T(1),}\\
&\scalemath{0.95}{\frac 1T \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \left (g_{t}(\mathring{\bm \lambda}(t)) - g_{t}(\bm \lambda(t))\right )\right ]=\operatorname{\mathcal O}\left (\frac{(N^2 (2NM+R)^2 + \epsilon_W N^2 (2NM+R)) C_W + (N^4 M^2+N^2 R^2)}{V}\right ) + o_T(V^{-1}).}
\end{align*}

As sketched in the main text, the first step is to \textit{i)} combine algorithmic guarantees for \texttt{AdaPFOL}\xspace (\Cref{thm:multi-hop stability decision making}) and \texttt{AdaBGD}\xspace (\Cref{thm:multi-hop utility decision making}), \textit{ii)} plug in the network stability assumption \Cref{lem:multi-hop utility network stability}, and \textit{iii)} make use of the Lyapunov DPP analysis in \Cref{lem:multi-hop utility Lyapunov}. Deferring these calculations to \Cref{lem:multi-hop utility tedious calc}, we can get
\begin{align}
\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]&\le -\frac{V}{\epsilon_W} \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \bigg (g_t(\mathring{\bm \lambda}(t)) - g_t(\bm \lambda(t))\bigg )\right ] + f(T) + \nonumber \\
&\quad g(T) \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]^{3/4} \log \operatornamewithlimits{\mathbb{E}}\left [M \sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ] + \nonumber \\
&\quad h(T) \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]^{7/8}.\label{eq:multi-hop utility self-bounding}
\end{align}
where
\begin{align*}
f(T)&= \epsilon_W^{-1} \operatorname{\mathcal O}\left ((N^2 (2NM+R)^2 + \epsilon_W N^2 (2NM+R)) C_W T + \frac{R(2NM+R)}{r^7} d^{14/3} (C^\lambda T^{1/2 - \delta_\lambda})^2\right .+\\
&\qquad \qquad \left .\left (\frac{R}{r} d^{2/3}+R\right ) (C^r T^{1/2 - \delta_r})^{1/4} V(L+G) T^{3/4}+\frac 12 N^2 ((NM)^2+2(NM)^2+2R^2) T\right ),\\
g(T)&=\epsilon_W^{-1} \operatorname{\mathcal O}\left ((2NM+R)^{1/4} M \sqrt{1+C^a T^{1/2 - \delta_a}} \log T \right ), \\
h(T)&=\epsilon_W^{-1} \operatorname{\mathcal O}\left ((2NM+R)^{1/8} \left (\frac Rr d^{2/3} + R\right ) (C^\lambda T^{1/2 - \delta_\lambda})^{1/4}\right ).
\end{align*}

\paragraph{Step 1 (Develop a Coarse Average Queue Length Bound).}
Recall the assumption that $g_t$ is uniformly bounded by $[-G,G]$. Therefore, the first term on the RHS of \Cref{eq:multi-hop utility self-bounding} is bounded by $2\frac{V}{\epsilon_W} GT$ in absolute value.
In \Cref{lem:3/4 and 7/8 self-bounding}, we develop a self-bounding property that says, if $y\le f+y^{3/4} g \log y +y^{7/8}$, then $y=\operatorname{\mathcal O}\left (f+g^4 \log^8\left (2(f^{1/8}+g^{1/2}+h)^2\right )+h^8\right )$.
Therefore, applying it to \Cref{eq:multi-hop utility self-bounding}, we have
\begin{align}
\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]&\le \operatorname{\mathcal O}\left (2\frac{V}{\epsilon_W} GT + f(T) + g(T)^4 \log^8\left (2(f(T)^{1/8}+g(T)^{1/2}+h(T))^2\right ) + h(T)^8\right ) \nonumber\\
&=\operatorname{\mathcal O}\left (\frac{V}{\epsilon_W} GT + f(T)\right ) + \operatorname{\mathcal O}_T\left (T^{1-2\delta_a} \log^8 \left (T^{1/4} + T^{1/4-\delta_a/2} + T^{1/4-\delta_\lambda/2}\right ) + T^{1-2\delta_\lambda}\right ) \nonumber\\
&=\operatorname{\mathcal O}\left (\frac{V}{\epsilon_W} GT + f(T)\right )+o_T(1). \label{eq:coarse queue length bound}
\end{align}

As mentioned in the proof sketch of this theorem, this only gives a $\frac 1T\operatornamewithlimits{\mathbb{E}}[\sum_{t=1}^T \lVert \bm Q(t)\rVert_1]=\operatorname{\mathcal O}_T(V)$ bound on the average queue length, which violates the system stability condition \Cref{eq:average queue}. However, this inequality can be used to derive the polynomial convergence result on the utility, which in turn refines the average queue length bound.

\paragraph{Step 2 (Yield Polynomial Convergence on the Utility).}
Moving the difference in the average utility in \Cref{eq:multi-hop utility self-bounding} to the LHS, we have
\begin{align*}
\frac{V}{\epsilon_W} \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \bigg (g_t(\mathring{\bm \lambda}(t)) - g_t(\bm \lambda(t))\bigg )\right ]&\le -\operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ] + f(T) + \nonumber \\
&\quad g(T) \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]^{3/4} \log \operatornamewithlimits{\mathbb{E}}\left [M \sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ] + \nonumber \\
&\quad h(T) \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \lVert \bm Q(t)\rVert_1\right ]^{7/8}.
\end{align*}

Plugging in the just-derived bound on average queue length, namely \Cref{eq:coarse queue length bound}, we have
\begin{align*}
&\quad \frac{V}{\epsilon_W} \operatornamewithlimits{\mathbb{E}}\left [\sum_{t=1}^T \bigg (g_t(\mathring{\bm \lambda}(t)) - g_t(\bm \lambda(t))\bigg )\right ]\\
