\label{lem:3/4 summation lemma}
For non-negative real numbers $x_1,x_2,\ldots,x_T\in \mathbb R$, we have
\begin{equation*}
\sum_{t=1}^T \frac{x_t}{\left (\sum_{s=1}^t x_s\right )^{1/4}} \le 2 \left (\sum_{t=1}^T x_t\right )^{3/4}.
\end{equation*}

\begin{equation*}
\sum_{t=1}^T \frac{x_t}{\left (\sum_{s=1}^t x_s\right )^{1/4}} \le 2 \left (\sum_{t=1}^T x_t\right )^{3/4}.
\end{equation*}

Prove by induction. The case when $T=1$ is obvious. Suppose that the conclusion holds for $T-1$, then consider some $x_T$:
\begin{align*}
&\quad \sum_{t=1}^T \frac{x_t}{\left (\sum_{s=1}^t x_s\right )^{1/4}}\\
&= \sum_{t=1}^{T-1} \frac{x_t}{\left (\sum_{s=1}^t x_s\right )^{1/4}} + \frac{x_T}{\left (\sum_{t=1}^T x_t\right )^{1/4}}\\
&\le 2 \left (\sum_{t=1}^{T-1} x_t\right )^{3/4} + \frac{x_T}{\left (\sum_{t=1}^T x_t\right )^{1/4}},
\end{align*}
so it suffices to prove $\left . x_T \middle / \left (\sum_{t=1}^T x_t\right )^{1/4}\right .\le 2 \left (\sum_{t=1}^T x_t\right )^{3/4} - 2 \left (\sum_{t=1}^{T-1} x_t\right )^{3/4}$. Notice that
\begin{align*}
&\quad \left (\left (\sum_{t=1}^T x_t\right )^{3/4} - \left (\sum_{t=1}^{T-1} x_t\right )^{3/4}\right )\left (\left (\sum_{t=1}^T x_t\right )^{1/4}+\left (\sum_{t=1}^{T-1} x_t\right )^{1/4}\right )\\
&=\left (\sum_{t=1}^T x_t \right ) + \left (\sum_{t=1}^T x_t \right )^{3/4} \left (\sum_{t=1}^{T-1} x_t \right )^{1/4} - \left (\sum_{t=1}^T x_t \right )^{1/4} \left (\sum_{t=1}^{T-1} x_t \right )^{3/4} - \left (\sum_{t=1}^{T-1} x_t \right ) \\
&\ge x_T,
\end{align*}
where the last inequality uses $\sum_{t=1}^T x_t\ge \sum_{t=1}^{T-1} x_t$ (follows from $x_T\ge 0$). Hence, due to the fact that
\begin{equation*}
\left . x_T \middle / 2 \left (\sum_{t=1}^T x_t\right )^{1/4}\right .\le \left . x_T \middle / \left (\sum_{t=1}^T x_t\right )^{1/4} + \left (\sum_{t=1}^{T-1} x_t\right )^{1/4}\right .,
\end{equation*}
the conclusion holds for $T$ as well.

\begin{align*}
&\quad \sum_{t=1}^T \frac{x_t}{\left (\sum_{s=1}^t x_s\right )^{1/4}}\\
&= \sum_{t=1}^{T-1} \frac{x_t}{\left (\sum_{s=1}^t x_s\right )^{1/4}} + \frac{x_T}{\left (\sum_{t=1}^T x_t\right )^{1/4}}\\
&\le 2 \left (\sum_{t=1}^{T-1} x_t\right )^{3/4} + \frac{x_T}{\left (\sum_{t=1}^T x_t\right )^{1/4}},
\end{align*}

\begin{align*}
&\quad \left (\left (\sum_{t=1}^T x_t\right )^{3/4} - \left (\sum_{t=1}^{T-1} x_t\right )^{3/4}\right )\left (\left (\sum_{t=1}^T x_t\right )^{1/4}+\left (\sum_{t=1}^{T-1} x_t\right )^{1/4}\right )\\
&=\left (\sum_{t=1}^T x_t \right ) + \left (\sum_{t=1}^T x_t \right )^{3/4} \left (\sum_{t=1}^{T-1} x_t \right )^{1/4} - \left (\sum_{t=1}^T x_t \right )^{1/4} \left (\sum_{t=1}^{T-1} x_t \right )^{3/4} - \left (\sum_{t=1}^{T-1} x_t \right ) \\
&\ge x_T,
\end{align*}

\begin{equation*}
\left . x_T \middle / 2 \left (\sum_{t=1}^T x_t\right )^{1/4}\right .\le \left . x_T \middle / \left (\sum_{t=1}^T x_t\right )^{1/4} + \left (\sum_{t=1}^{T-1} x_t\right )^{1/4}\right .,
\end{equation*}

\label{lem:4/3 lower bound}
Suppose that $x_1=0$, $x_2,x_3,\ldots,x_T\ge 0$, and $\lvert x_t-x_{t-1}\rvert\le 1$, $\forall t=2,3,\ldots,T$, then
\begin{equation*}
\sum_{t=1}^T x_t^{4/3} \ge 4^{-7/3} x_T^{7/3}.
\end{equation*}

\begin{equation*}
\sum_{t=1}^T x_t^{4/3} \ge 4^{-7/3} x_T^{7/3}.
\end{equation*}

As adjacent $x_t$'s differ by no more than $1$, $\lfloor x_T\rfloor < T$ and $x_{T-t}\ge x_T - t$. Therefore,
\begin{equation*}
\sum_{t=1}^T x_t^{4/3} \ge \sum_{t=0}^{\lfloor x_T\rfloor} x_{T-t}^{4/3}\ge \sum_{t=0}^{\lfloor x_T\rfloor} (x_T-t)^{4/3} \ge \sum_{t=0}^{\lfloor x_T\rfloor} \left (t^{4/3} + (x_T - \lfloor x_T\rfloor)^{4/3}\right )\ge \sum_{t=0}^{\lfloor x_T\rfloor} t^{4/3},
\end{equation*}
where the last step uses $(a+b)^{4/3} \ge a^{4/3} + b^{4/3}$.
As
\begin{equation*}
\sum_{i=0}^n i^{4/3} \ge \sum_{i=\lfloor \frac n2 \rfloor}^n i^{4/3} \ge \left (n - \left \lfloor \frac n2 \right \rfloor\right ) \left (\left \lfloor \frac n2 \right \rfloor\right )^{4/3} \ge \left (\left \lfloor \frac n2 \right \rfloor\right )^{7/3},
\end{equation*}
