\begin{equation*}
\sum_{t=1}^T x_t^{4/3} \ge \sum_{t=0}^{\lfloor x_T\rfloor} x_{T-t}^{4/3}\ge \sum_{t=0}^{\lfloor x_T\rfloor} (x_T-t)^{4/3} \ge \sum_{t=0}^{\lfloor x_T\rfloor} \left (t^{4/3} + (x_T - \lfloor x_T\rfloor)^{4/3}\right )\ge \sum_{t=0}^{\lfloor x_T\rfloor} t^{4/3},
